{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e2-harness-vs-product-sonnet-t5-sealed/cell-1HAS5k/src/parser.js","content":"// Parser for the configuration document described in the task.
//
// Produces a tree of nodes:
//   { kind: 'table', map: Map<string, Node>, headerMade: boolean }
//   { kind: 'aot', items: TableNode[] }
//   { kind: 'array', items: Node[] }
//   { kind: 'string', value: string }
//   { kind: 'integer', value: BigInt }
//   { kind: 'float', value: number }
//   { kind: 'boolean', value: boolean }

const DIGITS = String.raw`\d+(?:_\d+)*`
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:(?:\\.${DIGITS})(?:[eE][+-]?${DIGITS})?|[eE][+-]?${DIGITS})$`
)
const NAME_CHAR = /[A-Za-z0-9_-]/

class ParseError extends Error {}

function err(lineNo, reason) {
  return new ParseError(`line ${lineNo}: ${reason}`)
}

function newTable() {
  return { kind: 'table', map: new Map(), headerMade: false }
}

function skipWsc(cur) {
  while (cur.pos < cur.line.length && (cur.line[cur.pos] === ' ' || cur.line[cur.pos] === '\t')) {
    cur.pos++
  }
  if (cur.pos < cur.line.length && (cur.line[cur.pos] === '#' || cur.line[cur.pos] === ';')) {
    cur.pos = cur.line.length
  }
}

function parseBasicString(cur) {
  const lineNo = cur.lineNo
  cur.pos++ // opening quote
  let out = ''
  for (;;) {
    if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated string')
    const ch = cur.line[cur.pos]
    if (ch === '"') {
      cur.pos++
      return { kind: 'string', value: out }
    }
    if (ch === '\\') {
      cur.pos++
      if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated string')
      const esc = cur.line[cur.pos]
      if (esc === '"') { out += '"'; cur.pos++ }
      else if (esc === '\\') { out += '\\'; cur.pos++ }
      else if (esc === 'n') { out += '\n'; cur.pos++ }
      else if (esc === 't') { out += '\t'; cur.pos++ }
      else if (esc === 'r') { out += '\r'; cur.pos++ }
      else if (esc === '0') { out += '\0'; cur.pos++ }
      else if (esc === 'u') {
        cur.pos++
        if (cur.pos + 4 > cur.line.length) throw err(lineNo, 'unterminated string')
        const hex = cur.line.slice(cur.pos, cur.pos + 4)
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw err(lineNo, 'invalid escape \\u')
        out += String.fromCharCode(parseInt(hex, 16))
        cur.pos += 4
      } else {
        throw err(lineNo, `invalid escape \\${esc}`)
      }
    } else {
      out += ch
      cur.pos++
    }
  }
}

function parseLiteralString(cur) {
  const lineNo = cur.lineNo
  cur.pos++ // opening quote
  let out = ''
  for (;;) {
    if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated string')
    const ch = cur.line[cur.pos]
    if (ch === "'") {
      cur.pos++
      return { kind: 'string', value: out }
    }
    out += ch
    cur.pos++
  }
}

function parseName(cur) {
  if (cur.pos >= cur.line.length) throw err(cur.lineNo, 'expected a name')
  const ch = cur.line[cur.pos]
  if (ch === '"') return parseBasicString(cur).value
  if (ch === "'") return parseLiteralString(cur).value
  if (NAME_CHAR.test(ch)) {
    const start = cur.pos
    while (cur.pos < cur.line.length && NAME_CHAR.test(cur.line[cur.pos])) cur.pos++
    return cur.line.slice(start, cur.pos)
  }
  throw err(cur.lineNo, 'expected a name')
}

function parseDottedName(cur) {
  const segs = [parseName(cur)]
  for (;;) {
    skipWsc(cur)
    if (cur.pos < cur.line.length && cur.line[cur.pos] === '.') {
      cur.pos++
      skipWsc(cur)
      segs.push(parseName(cur))
    } else break
  }
  return segs
}

function parseIntBig(text) {
  let sign = 1n
  let t = text
  if (t[0] === '+') t = t.slice(1)
  else if (t[0] === '-') { sign = -1n; t = t.slice(1) }
  t = t.replace(/_/g, '')
  return sign * BigInt(t)
}

function parseFloatClean(text) {
  return Number(text.replace(/_/g, ''))
}

function parseBareValue(cur) {
  const start = cur.pos
  while (cur.pos < cur.line.length) {
    const ch = cur.line[cur.pos]
    if (ch === ' ' || ch === '\t' || ch === ',' || ch === ']' || ch === '}') break
    cur.pos++
  }
  const text = cur.line.slice(start, cur.pos)
  if (text === 'true') return { kind: 'boolean', value: true }
  if (text === 'false') return { kind: 'boolean', value: false }
  if (INT_RE.test(text)) return { kind: 'integer', value: parseIntBig(text) }
  if (FLOAT_RE.test(text)) return { kind: 'float', value: parseFloatClean(text) }
  throw err(cur.lineNo, `invalid value ${text}`)
}

function parseValue(cur, pathPrefix) {
  skipWsc(cur)
  if (cur.pos >= cur.line.length) throw err(cur.lineNo, 'expected a value')
  const ch = cur.line[cur.pos]
  if (ch === ',' || ch === ']' || ch === '}') throw err(cur.lineNo, 'expected a value')
  if (ch === '"') return parseBasicString(cur)
  if (ch === "'") return parseLiteralString(cur)
  if (ch === '[') return parseArrayValue(cur, pathPrefix)
  if (ch === '{') return parseInlineTableValue(cur, pathPrefix)
  return parseBareValue(cur)
}

function parseArrayValue(cur, pathPrefix) {
  const lineNo = cur.lineNo
  cur.pos++ // '['
  const items = []
  skipWsc(cur)
  if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated array')
  if (cur.line[cur.pos] === ']') { cur.pos++; return { kind: 'array', items } }
  for (;;) {
    const val = parseValue(cur, pathPrefix)
    items.push(val)
    skipWsc(cur)
    if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated array')
    const ch = cur.line[cur.pos]
    if (ch === ',') {
      cur.pos++
      skipWsc(cur)
      if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated array')
      if (cur.line[cur.pos] === ']') { cur.pos++; return { kind: 'array', items } }
      continue
    } else if (ch === ']') {
      cur.pos++
      return { kind: 'array', items }
    } else {
      throw err(lineNo, 'unterminated array')
    }
  }
}

function walkForAssign(table, prefix, names, valueNode, lineNo) {
  let node = table
  const path = prefix.slice()
  for (let i = 0; i < names.length - 1; i++) {
    path.push(names[i])
    const child = node.map.get(names[i])
    if (child === undefined) {
      const t = newTable()
      node.map.set(names[i], t)
      node = t
    } else if (child.kind === 'table') {
      node = child
    } else if (child.kind === 'aot') {
      node = child.items[child.items.length - 1]
    } else {
      throw err(lineNo, `${path.join('.')} is not a table`)
    }
  }
  const last = names[names.length - 1]
  path.push(last)
  if (node.map.has(last)) throw err(lineNo, `key ${path.join('.')} is defined twice`)
  node.map.set(last, valueNode)
}

function parseInlineTableValue(cur, pathPrefix) {
  const lineNo = cur.lineNo
  cur.pos++ // '{'
  const table = newTable()
  skipWsc(cur)
  if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated inline table')
  if (cur.line[cur.pos] === '}') { cur.pos++; return table }
  for (;;) {
    const segs = parseDottedName(cur)
    skipWsc(cur)
    if (cur.pos >= cur.line.length || cur.line[cur.pos] !== '=') {
      throw err(lineNo, 'expected = in an inline table')
    }
    cur.pos++
    skipWsc(cur)
    const fullPath = pathPrefix.concat(segs)
    const val = parseValue(cur, fullPath)
    walkForAssign(table, pathPrefix, segs, val, lineNo)
    skipWsc(cur)
    if (cur.pos >= cur.line.length) throw err(lineNo, 'unterminated inline table')
    const ch = cur.line[cur.pos]
    if (ch === ',') {
      cur.pos++
      skipWsc(cur)
      continue
    } else if (ch === '}') {
      cur.pos++
      return table
    } else {
      throw err(lineNo, 'unterminated inline table')
    }
  }
}

function parseHeaderLine(raw, startPos, lineNo) {
  const cur = { line: raw, pos: startPos, lineNo }
  cur.pos++ // first '['
  let isArray = false
  if (cur.pos < cur.line.length && cur.line[cur.pos] === '[') { isArray = true; cur.pos++ }
  skipWsc(cur)
  const segs = parseDottedName(cur)
  skipWsc(cur)
  if (cur.pos >= cur.line.length || cur.line[cur.pos] !== ']') {
    throw err(lineNo, 'unterminated table header')
  }
  cur.pos++
  if (isArray) {
    if (cur.pos >= cur.line.length || cur.line[cur.pos] !== ']') {
      throw err(lineNo, 'unterminated table header')
    }
    cur.pos++
  }
  skipWsc(cur)
  if (cur.pos < cur.line.length) throw err(lineNo, 'trailing text after a table header')
  return { segs, isArray }
}

function processHeader(root, segs, isArray, lineNo) {
  let node = root
  const path = []
  for (let i = 0; i < segs.length - 1; i++) {
    path.push(segs[i])
    const child = node.map.get(segs[i])
    if (child === undefined) {
      const t = newTable()
      node.map.set(segs[i], t)
      node = t
    } else if (child.kind === 'table') {
      node = child
    } else if (child.kind === 'aot') {
      node = child.items[child.items.length - 1]
    } else {
      throw err(lineNo, `${path.join('.')} is not a table`)
    }
  }
  const last = segs[segs.length - 1]
  path.push(last)
  const child = node.map.get(last)
  if (!isArray) {
    if (child === undefined) {
      const t = newTable()
      t.headerMade = true
      node.map.set(last, t)
      return { table: t, path }
    } else if (child.kind === 'table') {
      if (child.headerMade) throw err(lineNo, `table ${path.join('.')} is defined twice`)
      child.headerMade = true
      return { table: child, path }
    } else {
      throw err(lineNo, `${path.join('.')} is not a table`)
    }
  } else {
    if (child === undefined) {
      const arr = { kind: 'aot', items: [] }
      const t = newTable()
      arr.items.push(t)
      node.map.set(last, arr)
      return { table: t, path }
    } else if (child.kind === 'aot') {
      const t = newTable()
      child.items.push(t)
      return { table: t, path }
    } else {
      throw err(lineNo, `${path.join('.')} is not an array of tables`)
    }
  }
}

function parseAssignmentLine(raw, startPos, lineNo, currentTable, currentPrefix) {
  const cur = { line: raw, pos: startPos, lineNo }
  const segs = parseDottedName(cur)
  skipWsc(cur)
  if (cur.pos >= cur.line.length || cur.line[cur.pos] !== '=') {
    throw err(lineNo, 'expected key = value')
  }
  cur.pos++
  skipWsc(cur)
  const fullPath = currentPrefix.concat(segs)
  const val = parseValue(cur, fullPath)
  skipWsc(cur)
  if (cur.pos < cur.line.length) throw err(lineNo, 'trailing text after a value')
  walkForAssign(currentTable, currentPrefix, segs, val, lineNo)
}

export function parseDocument(lines) {
  const root = newTable()
  let current = root
  let currentPrefix = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    let j = 0
    while (j < raw.length && (raw[j] === ' ' || raw[j] === '\t')) j++
    if (j >= raw.length) continue
    const c = raw[j]
    if (c === '#' || c === ';') continue
    if (c === '[') {
      const { segs, isArray } = parseHeaderLine(raw, j, lineNo)
      const result = processHeader(root, segs, isArray, lineNo)
      current = result.table
      currentPrefix = result.path
    } else {
      parseAssignmentLine(raw, j, lineNo, current, currentPrefix)
    }
  }
  return root
}

export { ParseError }
"}

