/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import fs from 'node:fs'
import { parseDocument } from './parser.js'
import { toJsonString, collectKeys } from './output.js'

const mode = process.argv[2]
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let input
try {
  input = fs.readFileSync(0, 'utf8')
} catch {
  input = ''
}

const lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

try {
  const root = parseDocument(lines)
  if (mode === 'json') {
    process.stdout.write(toJsonString(root) + '\n')
  } else {
    const out = []
    collectKeys(root, '', out)
    process.stdout.write(out.length ? out.join('\n') + '\n' : '')
  }
  process.exit(0)
} catch (e) {
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
"}

